// N8N Function Node - Formatear error de ejecución (genérico)
const data = $input.all();

function formatErrorMessage(item) {
  const errorData = item.json;
  const execution = errorData.execution;
  const workflow = errorData.workflow;

  // Formatear el mensaje
  let message = '';

  // Encabezado del error
  message += `🚨 *ERROR EN AUTOMATIZACIÓN*\n\n`;

  // Información del workflow
  message += `📋 *Workflow:* ${workflow.name}\n`;
  message += `🆔 *ID:* ${workflow.id}\n\n`;

  // Información de la ejecución
  message += `⚡ *Ejecución:* #${execution.id}\n`;
  message += `🔄 *Modo:* ${execution.mode}\n`;

  // Si es un retry, mostrarlo
  if (execution.retryOf) {
    message += `🔁 *Reintento de:* #${execution.retryOf}\n`;
  }

  // Último nodo ejecutado
  message += `📍 *Último nodo:* ${execution.lastNodeExecuted}\n\n`;

  // Mensaje de error
  message += `❌ *Error:*\n${execution.error.message}\n\n`;

  // URL para revisar (opcional)
  if (execution.url) {
    message += `🔗 *Ver detalles:*\n${execution.url}\n\n`;
  }

  // Pie del mensaje
  message += `⏰ ${new Date().toLocaleString('es-ES')}`;

  return {
    json: {
      mensaje: message,
      error_summary: {
        workflow_name: workflow.name,
        execution_id: execution.id,
        error_message: execution.error.message,
        failed_node: execution.lastNodeExecuted
      }
    }
  };
}

// Procesar todos los items de entrada
return data.map(formatErrorMessage);

